{"command": "# Search for EF53 in big-endian format (EF 53 00 00)
python3 -c "
data = open('/tmp/test_fs.img', 'rb').read()
# Try different byte orders for 0xEF53
patterns = [
    bytes([0xEF, 0x53, 0x00, 0x00]),  # big-endian
    bytes([0x53, 0xEF, 0x00, 0x00]),  # little-endian  
]
for p in patterns:
    positions = [i for i in range(len(data)-3) if data[i:i+4] == p]
    if positions:
        print(f'Found pattern {p.hex()} at offsets: {positions[:5]}')
""}

{"command": "# Search for EF53 pattern in test8m.img
python3 -c "
data = open('/tmp/test8m.img', 'rb').read()
# Search for EF 53 pattern (could be big or little endian)
for i in range(len(data)-1):
    if data[i:i+2] == bytes([0xEF, 0x53]):
        print(f'Found EF53 at offset {i}: {data[i:i+8].hex()}')
        break
else:
    print('EF53 not found as big-endian')
    # Try little-endian: 53 EF
    for i in range(len(data)-1):
        if data[i:i+2] == bytes([0x53, 0xEF]):
            print(f'Found 53EF at offset {i}: {data[i:i+8].hex()}')
            break
